/// <summary>
/// XL tốt nghiệp coi là đậu khi có giá trị và khác "Không đạt" (không phân biệt hoa thường).
/// </summary>
private bool IsGraduationPassedLevel(string graduationLevel)
{
    if (graduationLevel == null)
        return false;
    string strLevel = graduationLevel.Trim();
    if (strLevel == "")
        return false;
    if (string.Compare(strLevel, "Không đạt", StringComparison.OrdinalIgnoreCase) == 0)
        return false;
    return true;
}

